  element: Element,
  clockMs: number,
  end: () => void,
): () => void {
  let waiting = true;
  const timer = setTimeout(() => {
    const running = releaseAnimationsOf(element);
    if (running.length === 0) {
      end();
      return;
    }
    void Promise.allSettled(
      running.map(async animation => animation.finished),
    ).then(() => {
      if (waiting) {
        end();
      }
    });
