  if (step.timer != null) {
    const kind = step.timer;
    const fire = () => {
      if (slot.live != null) {
        slot.live.timer = null;
      }
      apply(
        slot,
        pressGestureStep(slot.live?.gesture ?? idlePressGesture(), {
          kind: TIMER_EVENT[kind],
        }),
      );
